```python
import math
from functools import cmp_to_key

def run_query(rows: list[dict], query: dict) -> list[dict]:
    """
    Execute a simple SQL‑like query over a list of row dictionaries.
    """
    # ---------- helpers for 3‑valued logic ---------------------------------
    def _and(a, b):
        if a is False or b is False:
            return False
        if a is True and b is True:
            return True
        return None

    def _or(a, b):
        if a is True or b is True:
            return True
        if a is False and b is False:
            return False
        return None

    def _not(a):
        if a is True:
            return False
        if a is False:
            return True
        return None

    # ---------- evaluate a condition --------------------------------------
    def eval_cond(row, cond, aggs=None):
        op = cond[0]
        if op in ("=", "!=", "<", "<=", ">", ">="):
            lhs = get_operand(row, cond[1], aggs)
            rhs = get_operand(row, cond[2], aggs)
            if lhs is None or rhs is None:
                return None
            if op == "=":
                return lhs == rhs
            if op == "!=":
                return lhs != rhs
            if op == "<":
                return lhs < rhs
            if op == "<=":
                return lhs <= rhs
            if op == ">":
                return lhs > rhs
            if op == ">=":
                return lhs >= rhs
        elif op == "is_null":
            val = get_operand(row, cond[1], aggs)
            return val is None
        elif op == "in":
            val = get_operand(row, cond[1], aggs)
            lst = cond[2]
            if not lst:
                return False
            has_null_in_list = any(v is None for v in lst)
            if val is None:
                return None if has_null_in_list else False
            if val in lst:
                return True
            return None if has_null_in_list else False
        elif op == "between":
            val = get_operand(row, cond[1], aggs)
            lo = cond[2]
            hi = cond[3]
            if val is None:
                return None
            res1 = val >= lo
            res2 = val <= hi
            return _and(res1, res2)
        elif op == "and":
            return _and(eval_cond(row, cond[1], aggs), eval_cond(row, cond[2], aggs))
        elif op == "or":
            return _or(eval_cond(row, cond[1], aggs), eval_cond(row, cond[2], aggs))
        elif op == "not":
            return _not(eval_cond(row, cond[1], aggs))
        else:
            raise ValueError(f"Unknown operator {op}")

    def get_operand(row, operand, aggs):
        t = operand[0]
        if t == "col":
            return row[operand[1]]
        if t == "val":
            return operand[1]
        if t == "agg":
            func, arg = operand[1], operand[2]
            key = f"count(*)" if func == "count" and arg == "*" else f"{func}({arg})"
            return aggs[key]
        raise ValueError(f"Unknown operand type {t}")

    # ---------- extract aggregates used in SELECT and HAVING ---------------
    def collect_aggs(expr):
        aggs = set()
        if isinstance(expr, list):
            if len(expr) == 3 and isinstance(expr[0], str) and expr[0] in ("count", "count_distinct", "sum", "min", "max", "avg"):
                func, arg = expr[0], expr[1]
                if func == "count" and arg == "*":
                    aggs.add("count(*)")
                else:
                    aggs.add(f"{func}({arg})")
            elif expr[0] in ("and", "or"):
                for sub in expr[1:]:
                    aggs.update(collect_aggs(sub))
            elif expr[0] == "not":
                aggs.update(collect_aggs(expr[1]))
            elif expr[0] == "is_null":
                pass
            elif expr[0] in ("=", "!=", "<", "<=", ">", ">="):
                pass
            elif expr[0] == "in":
                pass
            elif expr[0] == "between":
                pass
            elif expr[0] == "agg":
                func, arg = expr[1], expr[2]
                if func == "count" and arg == "*":
                    aggs.add("count(*)")
                else:
                    aggs.add(f"{func}({arg})")
        return aggs

    # SELECT aggregates
    select_aggs = set()
    for item in query.get("select", []):
        if isinstance(item, list):
            if item[0] == "count" and item[1] == "*":
                select_aggs.add("count(*)")
            else:
                select_aggs.add(f"{item[0]}({item[1]})")

    # HAVING aggregates (may include aggregates not in SELECT)
    having_aggs = set()
    having_cond = query.get("having")
    if having_cond:
        def walk(cond):
            if isinstance(cond, list):
                op = cond[0]
                if op in ("and", "or"):
                    for c in cond[1:]:
                        walk(c)
                elif op == "not":
                    walk(cond[1])
                elif op == "agg":
                    func, arg = cond[1], cond[2]
                    if func == "count" and arg == "*":
                        having_aggs.add("count(*)")
                    else:
                        having_aggs.add(f"{func}({arg})")
                elif op in ("=", "!=", "<", "<=", ">", ">=", "is_null", "in", "between"):
                    pass
                elif op == "col" or op == "val":
                    pass
        walk(having_cond)

    all_aggs = select_aggs | having_aggs

    # ---------- filter rows by WHERE --------------------------------------
    where_cond = query.get("where")
    if where_cond:
        filtered_rows = [row for row in rows if eval_cond(row, where_cond) is True]
    else:
        filtered_rows = rows

    # ---------- grouping ---------------------------------------------------
    group_by = query.get("group_by", [])
    # group key tuple
    def make_key(row):
        return tuple(row[col] for col in group_by)

    # columns needed for aggregates
    agg_cols = set()
    for key in all_aggs:
        if key == "count(*)":
            continue
        func, arg = key.split("(", 1)
        arg = arg[:-1]
        agg_cols.add(arg)

    class GroupState:
        __slots__ = ("count_star", "counts", "sums", "mins", "maxs", "distincts")
        def __init__(self):
            self.count_star = 0
            self.counts = {}
            self.sums = {}
            self.mins = {}
            self.maxs = {}
            self.distincts = {}
        def add_row(self, row):
            self.count_star += 1
            for col in agg_cols:
                val = row[col]
                if val is None:
                    continue
                self.counts[col] = self.counts.get(col, 0) + 1
                self.sums[col] = self.sums.get(col, 0) + val
                if col not in self.mins or val < self.mins[col]:
                    self.mins[col] = val
                if col not in self.maxs or val > self.maxs[col]:
                    self.maxs[col] = val
                self.distincts.setdefault(col, set()).add(val)

    groups = {}
    if group_by:
        for row in filtered_rows:
            key = make_key(row)
            gs = groups.setdefault(key, GroupState())
            gs.add_row(row)
    else:
        # single implicit group
        gs = GroupState()
        for row in filtered_rows:
            gs.add_row(row)
        groups[()] = gs

    # ---------- compute aggregates for each group -------------------------
    def compute_aggs(gs: GroupState):
        aggs = {}
        for key in all_aggs:
            if key == "count(*)":
                aggs[key] = gs.count_star
            else:
                func, arg = key.split("(", 1)
                arg = arg[:-1]
                if func == "count":
                    aggs[key] = gs.counts.get(arg, 0)
                elif func == "count_distinct":
                    aggs[key] = len(gs.distincts.get(arg, set()))
                elif func == "sum":
                    cnt = gs.counts.get(arg, 0)
                    aggs[key] = gs.sums[arg] if cnt > 0 else None
                elif func == "min":
                    cnt = gs.counts.get(arg, 0)
                    aggs[key] = gs.mins[arg] if cnt > 0 else None
                elif func == "max":
                    cnt = gs.counts.get(arg, 0)
                    aggs[key] = gs.maxs[arg] if cnt > 0 else None
                elif func == "avg":
                    cnt = gs.counts.get(arg, 0)
                    aggs[key] = gs.sums[arg] // cnt if cnt > 0 else None
        return aggs

    # ---------- apply HAVING ----------------------------------------------
    result_groups = []
    for key, gs in groups.items():
        aggs = compute_aggs(gs)
        # build a dict with group columns for having evaluation
        row_for_having = {}
        for i, col in enumerate(group_by):
            row_for_having[col] = key[i]
        # evaluate having condition
        if having_cond:
            if eval_cond(row_for_having, having_cond, aggs) is not True:
                continue
        result_groups.append((key, aggs))

    # ---------- build output rows -----------------------------------------
    output_rows = []
    for key, aggs in result_groups:
        out = {}
        # group columns
        for i, col in enumerate(group_by):
            out[col] = key[i]
        # aggregates
        for item in query["select"]:
            if isinstance(item, str):
                out[item] = key[group_by.index(item)] if item in group_by else None
            else:
                func, arg = item[0], item[1]
                if func == "count" and arg == "*":
                    out["count(*)"] = aggs["count(*)"]
                else:
                    out[f"{func}({arg})"] = aggs[f"{func}({arg})"]
        output_rows.append(out)

    # ---------- distinct -----------------------------------------------
    distinct = query.get("distinct")
    if distinct:
        seen = set()
        uniq_rows = []
        for r in output_rows:
            # use frozenset of items; order doesn't matter
            key_tuple = frozenset(r.items())
            if key_tuple not in seen:
                seen.add(key_tuple)
                uniq_rows.append(r)
        output_rows = uniq_rows

    # ---------- order_by -----------------------------------------------
    order_by = query.get("order_by")
    if order_by:
        def cmp_rows(a, b):
            for col, dir_, nulls in order_by:
                va = a.get(col)
                vb = b.get(col)
                if va == vb:
                    continue
                # compare None handling
                if va is None:
                    if vb is None:
                        res = 0
                    else:
                        res = -1 if nulls in (None, "first") else 1
                elif vb is None:
                    res = 1 if nulls in (None, "first") else -1
                else:
                    res = -1 if va < vb else 1
                if dir_ == "desc":
                    res = -res
                if res != 0:
                    return res
            return 0
        output_rows.sort(key=cmp_to_key(cmp_rows))

    # ---------- offset/limit ---------------------------------------------
    offset = query.get("offset", 0)
    limit = query.get("limit")
    if offset is None:
        offset = 0
    if limit is not None:
        output_rows = output_rows[offset:offset+limit]
    else:
        output_rows = output_rows[offset:]

    return output_rows
